 void seed(){String[][]a={{"Tel Aviv","Ben Gurion Airport","TLV","Israel"},{"London","Heathrow Airport","LHR","United Kingdom"},{"Paris","Charles de Gaulle Airport","CDG","France"},{"New York","John F Kennedy International","JFK","United States"},{"Dubai","Dubai International","DXB","UAE"}};for(String[]x:a)airports.add(new A(x[0],x[1],x[2],x[3]));loadWorldwideAirports();}
 void loadWorldwideAirports(){new Thread(()->{try{java.net.URL u=new java.net.URL("https://davidmegginson.github.io/ourairports-data/airports.csv");java.io.BufferedReader r=new java.io.BufferedReader(new java.io.InputStreamReader(u.openStream()));String line;boolean first=true;ArrayList<A> fresh=new ArrayList<>();while((line=r.readLine())!=null){if(first){first=false;continue;}ArrayList<String>x=parseCsv(line);if(x.size()<14)continue;String type=x.get(2),name=x.get(3),city=x.get(10),iata=x.get(13),country=x.get(8);if(iata!=null&&!iata.isEmpty()&&!type.equals("closed"))fresh.add(new A(city,name,iata,country));}r.close();synchronized(airports){airports.clear();airports.addAll(fresh);}runOnUiThread(()->toast("Worldwide airports ready"));}catch(Exception e){}}).start();}
 ArrayList<String> parseCsv(String line){ArrayList<String>a=new ArrayList<>();StringBuilder b=new StringBuilder();boolean q=false;for(int i=0;i<line.length();i++){char ch=line.charAt(i);if(ch=='"'){if(q&&i+1<line.length()&&line.charAt(i+1)=='"'){b.append('"');i++;}else q=!q;}else if(ch==','&&!q){a.add(b.toString());b.setLength(0);}else b.append(ch);}a.add(b.toString());return a;}
 static class A{String city,name,iata,country;A(String a,String b,String c,String d){city=a;name=b;iata=c;country=d;}boolean hit(String q){return city.toLowerCase().contains(q)||name.toLowerCase().contains(q)||iata.toLowerCase().contains(q)||country.toLowerCase().contains(q);}}
